export function resolveLocale(req: Request, fallback: string = 'en'): Locale {
 const query = new URL(req.url).searchParams.get('lang');
 if (query === 'he' || query === 'en') return query;
 const cookie = req.headers.get('cookie')?.match(/(?:^|;\s*)extb_locale=(he|en)(?:;|$)/)?.[1];
 return cookie === 'he' || cookie === 'en' ? cookie : fallback === 'he' ? 'he' : 'en';
}
export function localizeHtml(html: string, locale: string): string {
 // Protect code, scripts, style and editable values even if a marker appears inside.
 const protectedParts: string[] = [];
 let result = html.replace(/<(script|style|textarea|code|pre)\b[^>]*>[\s\S]*?<\/\1>/gi, part => {
  protectedParts.push(part); return `\u0000EXTB_PROTECTED_${protectedParts.length - 1}\u0000`;
 });
 result = result.replace(/<!--extb-ui-->([\s\S]*?)<!--\/extb-ui-->/g, (_all, text: string) => {
  const key = text.trim(); return locale === 'he' && HEBREW[key] ? text.replace(key, HEBREW[key]) : text;
 });
 result = result.replace(/<[a-z][^>]*>/gi, tag => {
   return tag.replace(/ data-extb-i18n-(placeholder|title|aria-label)="([^"<>]*)"/g, (_marker, attr: string, text: string) => '').replace(/(placeholder|title|aria-label)="([^"<>]*)"/g, (original, attr: string, text: string) => {
     const marker = `data-extb-i18n-${attr}="${text}"`;
     return tag.includes(marker) && locale === 'he' && HEBREW[text] ? `${attr}="${HEBREW[text]}"` : original;
   });
 });
 result = result.replace(/<html\b[^>]*>/, `<html lang="${locale === 'he' ? 'he' : 'en'}" dir="${locale === 'he' ? 'rtl' : 'ltr'}">`);
 return result.replace(/\u0000EXTB_PROTECTED_(\d+)\u0000/g, (_all, index: string) => protectedParts[Number(index)] ?? '');
}
export async function localizeResponse(response: Response, locale: Locale, requestUrl?: string): Promise<Response> {
 if (!response.headers.get('Content-Type')?.includes('text/html') || response.status === 101) return response;
 let html = localizeHtml(await response.text(), locale);
 if (requestUrl) html = html.replace(/<a\b[^>]*>/g, tag => {
   const language = tag.match(/data-language="(he|en)"/)?.[1];
   if (!language || !/class="[^"]*\blanguage-switch\b/.test(tag)) return tag;
   const target = new URL(requestUrl); target.searchParams.set('lang', language);
   const relative = target.pathname + target.search + target.hash;
   const escaped = relative.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
   return tag.replace(/href="[^"]*"/, `href="${escaped}"`);
 });
 const result = new Response(html, response);
 result.headers.delete('Content-Length'); result.headers.set('Content-Language', locale);
 return result;
}
